import{_ as s,c as i,o as t,ag as a}from"./chunks/framework.Vyheyqg9.js";const g=JSON.parse('{"title":"What is GIT hooks? Which git hooks you are using on your current project and why?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Git/What_is_GIT_hooks_Which_git_hooks_you_are_using_on_your_current_project_and_why.md","filePath":"senior_growth/Git/What_is_GIT_hooks_Which_git_hooks_you_are_using_on_your_current_project_and_why.md"}'),o={name:"senior_growth/Git/What_is_GIT_hooks_Which_git_hooks_you_are_using_on_your_current_project_and_why.md"};function n(r,e,l,h,c,d){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="what-is-git-hooks-which-git-hooks-you-are-using-on-your-current-project-and-why" tabindex="-1">What is GIT hooks? Which git hooks you are using on your current project and why? <a class="header-anchor" href="#what-is-git-hooks-which-git-hooks-you-are-using-on-your-current-project-and-why" aria-label="Permalink to “What is GIT hooks? Which git hooks you are using on your current project and why?”">​</a></h1><h2 id="🔹-git-hooks" tabindex="-1"><span class="hub-section-number">1 </span>Git Hooks <a class="header-anchor" href="#🔹-git-hooks" aria-label="Permalink to “1 Git Hooks”">​</a></h2><p>This is an example policy, not evidence of installed hooks in this repository. Local hooks provide feedback; required CI/protected-branch/server policy must independently enforce acceptance. No push is permitted here.</p><p><strong>Git hooks</strong> are scripts that Git executes <strong>automatically at specific points</strong> in the Git workflow, such as before committing, pushing, or receiving changes. They allow you to <strong>enforce rules, automate tasks, and improve code quality</strong>.</p><hr><h2 id="_1️⃣-types-of-git-hooks" tabindex="-1"><span class="hub-section-number">2 </span>Types of Git Hooks <a class="header-anchor" href="#_1️⃣-types-of-git-hooks" aria-label="Permalink to “2 Types of Git Hooks”">​</a></h2><p>Git hooks are divided into <strong>client-side</strong> and <strong>server-side</strong> hooks:</p><table tabindex="0"><thead><tr><th>Type</th><th>Trigger Example</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Client-side</strong></td><td><code>pre-commit</code></td><td>Run checks before a commit is saved locally</td></tr><tr><td></td><td><code>commit-msg</code></td><td>Validate commit message format</td></tr><tr><td></td><td><code>pre-push</code></td><td>Run tests or linters before pushing</td></tr><tr><td><strong>Server-side</strong></td><td><code>pre-receive</code></td><td>Validate commits before accepting push on server</td></tr><tr><td></td><td><code>post-receive</code></td><td>Trigger deployments or notifications</td></tr></tbody></table><blockquote><p>Git normally looks in its hooks directory, configurable through core.hooksPath. A linked worktree can have a .git file, so do not assume .git/hooks is a normal directory in every checkout. Hook files need a valid interpreter/shebang and executable permission on applicable systems. Versioned hook sources are not automatically installed by cloning.</p></blockquote><hr><h2 id="_2️⃣-hooks-commonly-used-in-projects" tabindex="-1"><span class="hub-section-number">3 </span>Hooks Commonly Used in Projects <a class="header-anchor" href="#_2️⃣-hooks-commonly-used-in-projects" aria-label="Permalink to “3 Hooks Commonly Used in Projects”">​</a></h2><h3 id="client-side-hooks" tabindex="-1"><span class="hub-section-number">3.1 </span>Client-Side Hooks <a class="header-anchor" href="#client-side-hooks" aria-label="Permalink to “3.1 Client-Side Hooks”">​</a></h3><ol><li><p><strong>pre-commit</strong></p><ul><li>Purpose: Run <strong>linting, formatting, or unit tests</strong> before committing.</li><li>Minimal example: check whitespace in the staged diff without rewriting the worktree. This does not lint JavaScript or prove tests pass.</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -eu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div></li><li><p><strong>commit-msg</strong></p><ul><li>Purpose: Enforce <strong>commit message conventions</strong> (e.g., Conventional Commits).</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -eu</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./node_modules/.bin/commitlint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --edit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div></li><li><p><strong>pre-push</strong></p><ul><li>Purpose: Run <strong>unit tests or build checks</strong> before pushing.</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -eu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div></li></ol><hr><h3 id="server-side-hooks" tabindex="-1"><span class="hub-section-number">3.2 </span>Server-Side Hooks <a class="header-anchor" href="#server-side-hooks" aria-label="Permalink to “3.2 Server-Side Hooks”">​</a></h3><ol><li><p><strong>pre-receive</strong></p><ul><li>Purpose: Reject pushes that fail certain rules (e.g., forbidden branches, missing tests).</li></ul></li><li><p><strong>post-receive</strong></p><ul><li>Purpose: Trigger <strong>CI/CD pipelines</strong> or deployments after a successful push.</li></ul></li></ol><hr><h2 id="_3️⃣-example-hook-policy" tabindex="-1"><span class="hub-section-number">4 </span>Example hook policy <a class="header-anchor" href="#_3️⃣-example-hook-policy" aria-label="Permalink to “4 Example hook policy”">​</a></h2><ul><li><strong>pre-commit:</strong> Runs <strong>ESLint, Prettier, and format checks</strong> to ensure clean code before commit.</li><li><strong>commit-msg:</strong> Enforces <strong>Conventional Commit messages</strong> to maintain clear changelog.</li><li><strong>pre-push:</strong> Runs <strong>unit tests</strong> to avoid pushing broken code.</li><li><strong>Optional server-side (pre-receive):</strong> Prevent pushes to <code>main</code> without merge requests.</li></ul><p><strong>Benefits:</strong></p><ul><li>Maintains <strong>code quality and consistency</strong></li><li>Reduces <strong>broken builds</strong> in CI/CD</li><li>Enforces <strong>commit conventions</strong></li><li>Saves time in <strong>code review</strong> by catching issues early</li></ul><hr><h3 id="✅-summary" tabindex="-1"><span class="hub-section-number">4.1 </span>Summary <a class="header-anchor" href="#✅-summary" aria-label="Permalink to “4.1 Summary”">​</a></h3><ul><li><strong>Git hooks</strong> = scripts triggered at specific Git events.</li><li><strong>Client-side hooks</strong>: pre-commit, commit-msg, pre-push (quality checks, formatting, tests).</li><li><strong>Server-side hooks</strong>: pre-receive, post-receive (enforce rules, trigger CI/CD).</li><li><strong>Best Practice:</strong> Use hooks to <strong>automate checks</strong>, enforce <strong>standards</strong>, and prevent <strong>bad code</strong> from entering the repository.</li></ul><blockquote><p>Senior Tip: Combine <strong>linting, formatting, testing, and commit conventions</strong> in Git hooks for <strong>clean, reliable, and maintainable code</strong> across the team.</p></blockquote><h2 id="install-deliberately-and-check-staged-content" tabindex="-1"><span class="hub-section-number">5 </span>Install deliberately and check staged content <a class="header-anchor" href="#install-deliberately-and-check-staged-content" aria-label="Permalink to “5 Install deliberately and check staged content”">​</a></h2><p>The commit-msg example requires an already installed/configured local commitlint; the build/test hook requires those actual template scripts. Do not introduce dependencies or overwrite an existing core.hooksPath merely by copying this page. Inspect the existing manager (for example a configured Husky installation) and integrate through its reviewed mechanism. For the minimal fresh disposable fixture only, put the pre-commit script above in .githooks/pre-commit, then:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .githooks/pre-commit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --local</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.hooksPath</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .githooks</span></span></code></pre></div><p>A whole-tree formatter with --fix can change unrelated unstaged edits and produce a commit different from what was reviewed. Prefer check-only staged-aware tooling with bounded explicit paths. Be careful with partially staged files: checking the working file can inspect different bytes from the index. A full build/test may use the worktree, so CI must check a clean candidate checkout.</p><p>If using a temporary index/tree or a maintained staged runner, test preservation/restoration of partial changes and failure handling; never assume a script can safely auto-stage every rewrite.</p><p>pre-commit/commit-msg can be bypassed by supported Git options and users can change local configuration. Hooks are not a security boundary against a contributor controlling their own machine. Enforce required checks/review on the server/CI and protect privileged CI credentials from untrusted branches. Client hooks should report failure and terminate, not loop or silently swallow an error. Server deployment triggers also need their own controlled release policy.</p><p><strong>Actual validation2026-10-25:</strong> the executable shebang/set-eu/staged-whitespace hook was installed in a disposable Git2.54 repo. Bad staged whitespace with a clean-looking unstaged replacement blocked commit; HEAD/index/worktree bytes were preserved. Staging the correction allowed commit. Conversely a clean staged file with bad unstaged whitespace committed only the clean index bytes and left the worktree untouched. No whole-tree auto-fix ran. The commitlint/full-build hook examples were not installed/executed; hosted enforcement was not tested.</p><p>Official references checked2026-10-25: <a href="https://git-scm.com/docs/githooks" target="_blank" rel="noreferrer">hook execution/bypass</a>, <a href="https://git-scm.com/docs/git-config" target="_blank" rel="noreferrer">core.hooksPath</a>, <a href="https://git-scm.com/docs/git-diff" target="_blank" rel="noreferrer">staged diff checks</a>.</p><h2 id="separate-practice" tabindex="-1"><span class="hub-section-number">6 </span>Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “6 Separate practice”">​</a></h2><p>Use the <a href="./../../practice/engineering/git/What_is_GIT_hooks_Which_git_hooks_you_are_using_on_your_current_project_and_why.html">focused acceptance and evidence requirements</a>. All learner practice remains outstanding.</p>`,35)])])}const k=s(o,[["render",n]]);export{g as __pageData,k as default};
